/* Browser UI. All requests use this computer's local server. */
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => Array.from(root.querySelectorAll(s));
const content = $('#app-content');
const dialog = $('#detail-dialog');
const state = {tab:'students',boot:null,filters:{lecturer:[],recitation:[],unit:[],class:[],curric:[]},q:'',page:1,report:'letters',assessment:'',excludeZero:false,includeW:true,includeTZ:false,reviewOnly:false,tzOnly:false,importKind:'regis',preview:null,importFile:null,importSemester:'',importScope:'semester',importSections:[],policyTerm:'',policy:null,cache:{},pending:0,filtersTouched:false};
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const num = (v,d=1) => v===null||v===undefined||v===''?'—':Number.isFinite(Number(v))?Number(v).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d}):esc(v);
const integer = v => num(v,0);
const courseName = () => state.boot?.course?.name || 'Course';
function calendarTerm(){const date=new Date();return (date.getMonth()>=7?'Fa':date.getMonth()>=4?'Su':'Sp')+String(date.getFullYear()).slice(-2);}
const percent = v => v===null||v===undefined?'—':`${num(v)}%`;
const termLabel = value => state.boot?.semesters?.find(s=>s.semester===value)?.label||value||'All semesters';
const list = value => Array.isArray(value)?value:value?[value]:[];
const grade = value => value?`<span class="badge ${value==='W'?'gray':value==='TZ'?'amber':value==='F'||value==='XF'?'red':'green'}">${esc(value)}</span>`:'<span class="muted">—</span>';
const empty = (title,description) => `<div class="empty-state"><span class="empty-symbol" aria-hidden="true">○</span><h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
const metric = (label,value,sub='',featured=false) => `<div class="metric${featured?' featured':''}"><span class="metric-label">${esc(label)}</span><div class="metric-value">${value}</div>${sub?`<div class="metric-sub">${esc(sub)}</div>`:''}</div>`;
const button = (text,action,primary=false,extra='') => `<button class="button${primary?' primary':''}" data-action="${action}" ${extra}>${text}</button>`;
function notify(message,error=false){const node=$('#notification');node.textContent=message;node.classList.toggle('error',error);node.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>node.hidden=true,error?10000:6500);}
async function request(path,options={}){
  const headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json','X-App-Token':state.boot?.token||state.boot?.csrf_token||state.boot?.app_token||''}:{}),...options.headers};
  const response=await fetch('/api'+path,{...options,headers,cache:'no-store'});
  let data;try{data=await response.json();}catch{throw new Error('The local app did not return a valid response. Please reopen the app and try again.');}
  if(!response.ok)throw new Error(data.error||'The request could not be completed.');
  return data;
}
const recordFilters=window.Math135Filters.create({state,getOptions:(key,rules)=>availableFilterOptions(key,rules),termLabel,onApply:async()=>{state.filtersTouched=true;state.page=1;await loadTab();}});
function query(extra={}){const q=new URLSearchParams();for(const [key,value] of Object.entries({...state.filters,...extra})){if(Array.isArray(value)){value.forEach(v=>q.append(key,v));}else if(value!==''&&value!==null&&value!==undefined)q.set(key,value);}const rules=recordFilters.queryValue();if(rules)q.set('filter_rules',rules);return q.toString();}
function exportLink(type){return '/api/export?'+query({type,assessment_id:state.assessment,exclude_zero:state.excludeZero?'1':'0',include_w:state.includeW?'1':'0',include_tz:state.includeTZ?'1':'0',mismatches_only:state.reviewOnly?'1':'0',tz_only:state.tzOnly?'1':'0',q:state.q});}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function availableFilterOptions(key,rules=state.filterRules){
  const terms=recordFilters.scopeTerms(rules),all=state.boot?.semesters||[];
  if(terms.length===all.length)return state.boot.filters?.[key]||[];
  const rows=new Map();
  for(const term of terms)for(const item of state.boot.filters_by_semester?.[term]?.[key]||[]){
    const value=String(item.value),row=rows.get(value);
    if(row)row.count+=Number(item.count||0);else rows.set(value,{...item,count:Number(item.count||0)});
  }
  return [...rows.values()].sort((a,b)=>String(a.label).localeCompare(String(b.label),undefined,{numeric:true}));
}
function defaultSemesters(){recordFilters.setSemesters(['reports','review'].includes(state.tab)?[currentTerm()]:[]);}
function importDefaultSemester(){const terms=recordFilters.scopeTerms();return terms.length===1?terms[0]:currentTerm();}
function normalizeFilterSelections(){recordFilters.normalize();}
function filters(actions=''){return recordFilters.renderToolbar(actions);}
function activeFilters(){return recordFilters.describe();}
function printLabel(){return `<p class="print-heading">${esc(activeFilters())} · Prepared ${esc(new Date().toLocaleDateString())}</p>`;}
async function loadTab(){
  normalizeFilterSelections();
  if(state.assessment&&!state.boot.assessments.some(a=>String(a.assessment_id)===String(state.assessment)&&recordFilters.scopeTerms().includes(a.semester)))state.assessment='';
  const ticket=++state.pending;
  $$('.nav-button').forEach(n=>{n.classList.toggle('active',n.dataset.tab===state.tab);n.setAttribute('aria-current',n.dataset.tab===state.tab?'page':'false');});
  document.title=`${{students:'Students',reports:'Reports',imports:'Imports',review:'Grade review',settings:'Course settings'}[state.tab]} · ${courseName()} Records`;
  content.innerHTML='<div class="loading-state"><span class="spinner"></span><p>Loading records…</p></div>';
  try{
    if(state.tab==='students'){const data=await request('/students?'+query({q:state.q,page:state.page}));if(ticket!==state.pending)return;state.cache.students=data;renderStudents(data);}
    if(state.tab==='reports'){const data=await request('/reports?'+query({assessment_id:state.assessment,exclude_zero:state.excludeZero?'1':'0',include_w:state.includeW?'1':'0',include_tz:state.includeTZ?'1':'0'}));if(ticket!==state.pending)return;state.cache.reports=data;renderReports(data);}
    if(state.tab==='imports'){const data=await request('/imports');if(ticket!==state.pending)return;state.cache.imports=data.rows||[];renderImports();}
    if(state.tab==='review'){const data=await request('/grade-review?'+query({mismatches_only:state.reviewOnly?'1':'0',tz_only:state.tzOnly?'1':'0'}));if(ticket!==state.pending)return;state.cache.review=data;renderReview(data);}
    if(state.tab==='settings'){if(!state.policyTerm)state.policyTerm=currentTerm();const data=await request('/policy?semester='+encodeURIComponent(state.policyTerm));if(ticket!==state.pending)return;state.policy=data.policy;renderSettings();}
  }catch(error){if(ticket!==state.pending)return;content.innerHTML=heading('Something needs attention','Your saved records have not been changed.')+`<div class="note error page-error">${esc(error.message)}<div class="action-row">${button('Try again','reload',true)}</div></div>`;}
}
function currentTerm(){return state.boot.semesters.find(s=>s.status==='current')?.semester||state.boot.semesters.at(-1)?.semester||calendarTerm();}
function renderStudents(data){
  const rows=data.rows||[],page=data.page||state.page,size=data.page_size||50,total=data.total||0;
  content.innerHTML=heading('Students','Find a student, follow their course history, and see every recorded attempt.')+filters(`<a class="button" href="${attr(exportLink('students'))}">Export results</a>`)+`<div class="metric-grid">${metric('Student records',integer(state.boot.summary?.records),'Across the saved semesters',true)}${metric('Unique students',integer(state.boot.summary?.students),'Matched by student identifiers')}${metric('Semesters',integer(state.boot.semesters.length),'Summer sessions are excluded')}${metric('Matching students',integer(total),'With the selected filters')}</div><section class="card students-card"><div class="toolbar"><form id="student-search-form" class="search-wrap"><label class="screen-reader" for="student-search">Search students by name, RUID, or NetID</label><input id="student-search" class="search-input" type="search" placeholder="Search by name, RUID, or NetID" value="${attr(state.q)}" autocomplete="off"></form>${button('Search','search',true)}<span class="result-count">${integer(total)} ${total===1?'student':'students'}</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Student</th><th>NetID</th><th>Recorded semesters</th><th class="numeric">Attempts</th><th>Latest grade</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="student-identity"><button class="row-link" data-student="${attr(r.ruid)}">${esc(r.name)}</button><span class="student-id">RUID ${esc(r.ruid)}</span></span></td><td>${esc(r.netid)||'—'}</td><td>${list(r.semesters).map(t=>`<span class="chip">${esc(typeof t==='object'?t.semester:t)}</span>`).join('')}</td><td class="numeric">${integer(r.attempts)}</td><td><span class="student-latest">${grade(r.latest_grade)}<span class="student-id">${esc(r.latest_semester?termLabel(r.latest_semester):'')}</span></span></td><td><button class="button small" data-student="${attr(r.ruid)}">View history →</button></td></tr>`).join('')}</tbody></table></div>`:empty('No students found','Try a different name or fewer filters.')}<div class="table-footer"><span>${total?`${integer((page-1)*size+1)}–${integer(Math.min(page*size,total))} of ${integer(total)}`:'No matching records'}</span><div class="pagination">${button('← Previous','previous-page',false,page<=1?'disabled':'')}<span class="small-text" style="padding:9px">Page ${integer(page)}</span>${button('Next →','next-page',false,page*size>=total?'disabled':'')}</div></div></section><p class="small-text muted">An attempt is a distinct semester with a recorded grade, including W. A current enrollment without a grade appears as in progress.</p>`;
}
async function showStudent(ruid){
  $('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="detail-title">Student history</h2><button class="dialog-close" data-action="close-dialog" aria-label="Close">×</button></div><div class="loading-state"><span class="spinner"></span></div>`;if(!dialog.open)dialog.showModal();
  try{const r=await request('/students/'+encodeURIComponent(ruid));const records=r.records||[];state.cache.detail=r;
    $('#dialog-content').innerHTML=`<div class="dialog-header"><div><h2 id="detail-title">${esc(r.name)}</h2><p>RUID ${esc(r.ruid)}${r.netid?' · '+esc(r.netid):''}</p></div><button class="dialog-close" data-action="close-dialog" aria-label="Close student history">×</button></div><div class="dialog-body"><div class="metric-grid">${metric('Attempts at '+courseName(),integer(r.attempts),'Recorded grades, including withdrawals',true)}${metric('Semesters on record',integer(records.length),'Includes current enrollments')}${metric('Withdrawal attempts',integer(records.filter(x=>x.official_grade==='W').length),'Semesters with a W grade')}${metric('In progress',integer(records.filter(x=>!x.official_grade&&x.active!==0).length),'Enrollments without a final grade')}</div><p class="small-text muted">Attempt semesters: ${list(r.attempt_semesters).map(termLabel).map(esc).join(', ')||'No completed attempts yet'}.</p><h3 class="section-title">Course history</h3><div class="table-scroll"><table><thead><tr><th>Semester / section</th><th>Official grade</th><th class="numeric">Course average</th><th>School / class / major</th><th></th></tr></thead><tbody>${records.map((x,i)=>`<tr><td><strong>${esc(termLabel(x.semester))}</strong><span class="secondary-text">Section ${esc(x.section||'—')} · Lecturer: ${esc(x.lecturer||'Unmapped')} · Recitation: ${esc(x.recitation||'Unmapped')}${x.active===0?' · Removed from latest roster':''}</span></td><td>${x.official_grade?grade(x.official_grade):'<span class="badge gray">In progress</span>'}</td><td class="numeric">${percent(x.course_average)}<span class="secondary-text">${esc(statusLabel(x.average_status||''))}</span></td><td>${esc(x.unit||'—')} / ${esc(x.class||'—')} / ${esc(x.curric||'—')}</td><td><button class="button small" data-score-toggle="${i}" aria-expanded="false">Scores</button></td></tr><tr class="student-assessment-row" data-score-row="${i}" hidden><td colspan="5">${x.scores?.length?`<div class="table-scroll"><table><thead><tr><th>Assessment</th><th class="numeric">Score / 100</th><th>Status</th></tr></thead><tbody>${x.scores.map(s=>`<tr><td>${esc(s.label)}</td><td class="numeric">${num(s.percent)}</td><td>${esc(statusLabel(s.status||''))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="small-text muted">No assessment scores are recorded for this semester.</p>'}</td></tr>`).join('')}</tbody></table></div><div class="action-row">${button('Print history','print')}${button('Done','close-dialog',true)}</div></div>`;
  }catch(error){$('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="detail-title">Student history</h2><button class="dialog-close" data-action="close-dialog" aria-label="Close">×</button></div><div class="dialog-body"><p class="note error">${esc(error.message)}</p></div>`;}
}
function statusLabel(s){return ({accepted_historical:'Saved historical average',verified:'Verified',reconstructed:'Calculated',incomplete:'Incomplete data',match:'Matches',discrepancy:'Review needed',no_proposal:'No proposed grade',special_status:'Special grade',committed:'Applied',undone:'Undone',updated:'Updated',new:'Added',selected:'Recorded',not_available:'Not available',present:'Recorded',missing:'Missing',excused:'Excused',accepted:'Accepted historical average',accepted_saved:'Saved historical average'})[s]||String(s).replace(/_/g,' ');}
function chart(bins,label){
  if(!bins?.length||!bins.some(x=>Number(x.count)>0))return empty('No scores to chart','Choose an assessment with recorded scores, or adjust the filters.');
  const w=720,h=290,left=48,right=16,top=26,bottom=51,plotH=h-top-bottom,plotW=w-left-right,max=Math.max(...bins.map(x=>Number(x.count)||0)),ceiling=Math.max(1,Math.ceil(max/5)*5),gap=Math.min(20,plotW/bins.length*.23),bw=plotW/bins.length-gap;
  let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${attr(label)}"><title>${esc(label)}</title>`;
  for(let i=0;i<=4;i++){const y=top+plotH*i/4;svg+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#e4eae3"/><text x="${left-10}" y="${y+4}" text-anchor="end">${integer(ceiling*(1-i/4))}</text>`;}
  bins.forEach((b,i)=>{const x=left+i*(plotW/bins.length)+gap/2,bh=Number(b.count)/ceiling*plotH;svg+=`<rect class="bar" x="${x}" y="${top+plotH-bh}" width="${bw}" height="${Math.max(0,bh)}" rx="3"><title>${esc(b.label)}: ${integer(b.count)}</title></rect><text x="${x+bw/2}" y="${top+plotH-bh-8}" text-anchor="middle" style="fill:#31574c;font-size:10px">${integer(b.count)}</text><text x="${x+bw/2}" y="${h-bottom+19}" text-anchor="middle"${bins.length>14?' transform="rotate(-40 '+(x+bw/2)+' '+(h-bottom+19)+')"':''}>${esc(b.label)}</text>`;});return svg+'</svg>';
}
function renderReports(data){
  const s=data.summary||{},a=data.assessment,letters=data.letters||[];const choices=state.boot.assessments.filter(x=>recordFilters.scopeTerms().includes(x.semester));
  const tabs=[['letters','Letter grades'],['assessment','Assessment scores'],['enrollment','Enrollment & DF rates'],['tz','TZ follow-up']];
  content.innerHTML=heading('Reports','Explore course outcomes and assessment scores with consistent semester and student filters.')+filters(`${button('Print / save PDF','print')}<a class="button" href="${attr(exportLink(state.report==='enrollment'?'letters':state.report))}">Export CSV</a>`)+printLabel()+`<div class="segmented" aria-label="Report type">${tabs.map(([key,label])=>`<button data-report="${key}" class="${state.report===key?'active':''}">${label}</button>`).join('')}</div>`;
  if(state.report==='letters')content.insertAdjacentHTML('beforeend',`<div class="toggle-row"><label><input type="checkbox" id="include-w"${state.includeW?' checked':''}> Include W in letter distribution</label><label><input type="checkbox" id="include-tz"${state.includeTZ?' checked':''}> Include TZ in letter distribution</label><span class="small-text muted">XF always counts as F in calculations.</span></div><div class="metric-grid">${metric('Mean GPA',num(s.mean_gpa,2),'Your 4.0 grade-point scale',true)}${metric('Median GPA',num(s.median_gpa,2),'Median of included grade points')}${metric('GPA records',integer(s.gpa_count),'W, TZ, and ungraded records excluded')}${metric('Roster size',integer(s.enrolled),'All students on the selected roster')}</div><div class="two-column"><section class="card"><div class="card-header"><div><h2>Letter-grade distribution</h2><p>${esc(activeFilters())}</p></div></div><div class="card-body chart-wrap">${chart(letters.map(g=>({...g,label:g.grade||g.label})),'Letter-grade distribution')}<p class="chart-caption">The W and TZ checkboxes affect this distribution. GPA uses A = 4, B+ = 3.5, B = 3, C+ = 2.5, C = 2, D = 1, F/XF = 0.</p></div></section><section class="card"><div class="card-header"><h2>Grade counts</h2></div><div class="table-scroll"><table><thead><tr><th>Grade</th><th class="numeric">Students</th><th class="numeric">Percent</th></tr></thead><tbody>${letters.map(g=>`<tr><td>${grade(g.grade||g.label)}</td><td class="numeric">${integer(g.count)}</td><td class="numeric">${percent(g.percent)}</td></tr>`).join('')||'<tr><td colspan="3">No recorded grades in this selection.</td></tr>'}</tbody></table></div></section></div>`);
  if(state.report==='assessment')content.insertAdjacentHTML('beforeend',`<div class="report-controls"><div class="field wide"><label for="assessment-select">Assessment</label><select id="assessment-select"><option value="">Choose an assessment…</option>${choices.map(x=>`<option value="${attr(x.assessment_id)}"${String(x.assessment_id)===String(state.assessment)?' selected':''}>${esc((recordFilters.scopeTerms().length===1?'':termLabel(x.semester)+' · ')+x.label)}</option>`).join('')}</select></div></div><div class="toggle-row"><label><input type="checkbox" id="exclude-zero"${state.excludeZero?' checked':''}> Exclude scores of zero from statistics</label><span class="small-text muted">Blank and excused scores are always excluded. Scores are shown out of 100.</span></div>${a?assessmentReport(a):`<section class="card">${empty('Choose an assessment','Select a semester and assessment above to see its histogram and statistics.')}</section>`}`);
  if(state.report==='enrollment')content.insertAdjacentHTML('beforeend',`<div class="metric-grid">${metric('Total enrolled',integer(s.enrolled),'Everyone on the semester roster',true)}${metric('Withdrew',integer(s.withdrawn),'Students with a W grade')}${metric('Did not withdraw',integer(s.remaining),'Students without W')}${metric('Withdrawal rate',s.enrolled?percent(s.withdrawn/s.enrolled*100):'—','W ÷ total enrolled')}</div><div class="two-column"><section class="card"><div class="card-header"><h2>Course outcome rates</h2></div><div class="card-body"><dl class="stat-list"><div><dt>DFW rate</dt><dd>${percent(s.dfw_rate)}</dd></div><div><dt>DF rate</dt><dd>${percent(s.df_rate)}</dd></div><div><dt>D / F / XF / W records</dt><dd>${integer(s.dfw_count)}</dd></div><div><dt>D / F / XF records</dt><dd>${integer(s.df_count)}</dd></div><div><dt>DFW denominator</dt><dd>${integer(s.dfw_denominator)}</dd></div><div><dt>DF denominator</dt><dd>${integer(s.df_denominator)}</dd></div></dl><p class="note">DFW includes D, F, XF, and W. DF includes D, F, and XF and excludes W from its denominator. TZ and pending grades are excluded from both rate denominators.</p></div></section><section class="card"><div class="card-header"><h2>How these counts work</h2></div><div class="card-body small-text"><p>Total enrollment is the complete saved roster. Students with W are counted as withdrawn; everyone without W is counted as having not withdrawn.</p><p>Earlier withdrawals that do not appear on the roster are not estimated. If you select several semesters, these are student-semester counts, so a returning student may appear more than once.</p><p class="muted">${esc(activeFilters())}</p></div></section></div>`);
  if(state.report==='tz')content.insertAdjacentHTML('beforeend',`<section class="card"><div class="card-header"><div><h2>TZ follow-up</h2><p>${integer(data.tz_rows?.length||0)} records requiring follow-up. TF and TTZ are treated as TZ.</p></div><a class="button small" href="${attr(exportLink('tz'))}">Export list</a></div>${tzTable(data.tz_rows||[])}</section>`);
}
function assessmentReport(a){const s=a.stats||{};return `<div class="metric-grid">${metric('Mean score',percent(s.mean),'Normalized to 100',true)}${metric('Median score',percent(s.median),'Normalized to 100')}${metric('Included scores',integer(s.count),'Used in the statistics')}${metric('Excluded / missing',integer((s.missing||0)+(s.zeros_excluded||0)),`${s.missing||0} blank / excused · ${s.zeros_excluded||0} zeros excluded`)}</div><div class="two-column"><section class="card"><div class="card-header"><div><h2>${esc(a.name)}</h2><p>Assessment score distribution · out of 100</p></div></div><div class="card-body chart-wrap">${chart(a.bins||[],a.name+' score distribution')}<p class="chart-caption">Extra-credit scores above 100 are retained. ${state.excludeZero?'Zero scores are excluded.':'Zero scores are included.'} Blank and excused scores are excluded.</p></div></section><section class="card"><div class="card-header"><h2>Score statistics</h2></div><div class="card-body"><dl class="stat-list"><div><dt>Mean</dt><dd>${num(s.mean)}</dd></div><div><dt>Median</dt><dd>${num(s.median)}</dd></div><div><dt>Standard deviation</dt><dd>${num(s.stddev)}</dd></div><div><dt>Minimum</dt><dd>${num(s.min)}</dd></div><div><dt>25th percentile</dt><dd>${num(s.q1)}</dd></div><div><dt>75th percentile</dt><dd>${num(s.q3)}</dd></div><div><dt>Maximum</dt><dd>${num(s.max)}</dd></div><div><dt>Score count</dt><dd>${integer(s.count)}</dd></div></dl></div><div class="table-scroll"><table><thead><tr><th>Score range</th><th class="numeric">Students</th></tr></thead><tbody>${(a.bins||[]).map(b=>`<tr><td>${esc(b.label)}</td><td class="numeric">${integer(b.count)}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
function tzTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>Student</th><th>Semester</th><th>Section</th><th>Lecturer</th><th>Recitation instructor</th><th>Contact</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="row-link" data-student="${attr(r.ruid)}">${esc(r.name)}</button><span class="secondary-text">${esc(r.netid||r.ruid)}</span></td><td>${esc(termLabel(r.semester))}</td><td>${esc(r.section||'—')}</td><td>${esc(r.lecturer||r.instructor||'Unmapped')}</td><td>${esc(r.recitation||'Unmapped')}</td><td>${esc(r.email||r.instructor_email||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('No TZ records in this selection','Choose another semester or adjust the filters to see other follow-up records.');}
function renderReview(data){
  const rows=data.rows||[],s=data.summary||{},counts={};rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);
  content.innerHTML=heading('Grade review','Compare instructor proposals with the course policy, and see exactly why a grade differs.')+filters(`${button('Import proposed grades','open-proposals',true)}<a class="button" href="${attr(exportLink('grade-review'))}">Export review</a>`)+printLabel()+`<div class="metric-grid">${metric('Grades needing review',integer(s.discrepancy??s.discrepancies??counts.discrepancy??0),'Proposed and anticipated grades differ',true)}${metric('Matching grades',integer(s.match??s.matches??counts.match??0),'Proposed and anticipated grades agree')}${metric('Incomplete data',integer(s.incomplete??counts.incomplete??0),'Missing required score information')}${metric('No proposal yet',integer(s.no_proposal??counts.no_proposal??0),'Ready for instructor grade import')}</div><section class="card"><div class="toolbar"><label class="check-option"><input type="checkbox" id="review-only"${state.reviewOnly?' checked':''}> Show discrepancies only</label><label class="check-option"><input type="checkbox" id="tz-only"${state.tzOnly?' checked':''}> TZ students only</label><span class="result-count">${integer(rows.length)} records</span></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Student / section</th><th>Semester</th><th class="numeric">Average</th><th>Base</th><th>Final exam</th><th>Anticipated</th><th>Proposed</th><th>Official</th><th>Review</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="row-link" data-student="${attr(r.ruid)}">${esc(r.name)}</button><span class="secondary-text">${esc(r.netid||r.ruid)} · Section ${esc(r.section||'—')}</span><span class="secondary-text">Lecturer: ${esc(r.lecturer||r.instructor||'Unmapped')} · Recitation: ${esc(r.recitation||'Unmapped')}</span></td><td>${esc(termLabel(r.semester))}</td><td class="numeric">${percent(r.course_average)}</td><td>${grade(r.base_grade)}</td><td>${grade(r.final_exam_grade)}</td><td>${grade(r.anticipated_grade)}${r.bump_applied?'<span class="secondary-text">Bump applied</span>':''}</td><td>${grade(r.proposed_grade)}</td><td>${grade(r.official_grade)}</td><td><span class="badge ${r.status==='match'?'green':r.status==='discrepancy'?'red':r.status==='incomplete'?'amber':'gray'}">${esc(statusLabel(r.status))}</span><div class="review-reason">${esc(r.reason||'')}${r.missing?.length?'<br>Missing: '+esc(list(r.missing).join(', ')):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No grade-review records match','Try turning off the discrepancy filter, or choose another semester.')}</section><p class="note">Official REGIS grades, instructor proposals, and anticipated grades are kept separately. Missing required components produce “incomplete data,” not an incorrect-grade flag. XF counts as F in calculations.</p>`;
}
function semesterOptions(value,autodetect=false){const terms=[...state.boot.semesters];for(let year=new Date().getFullYear();year<=new Date().getFullYear()+3;year++)for(const [prefix,label] of [['Sp','Spring'],['Fa','Fall']]){const semester=prefix+String(year).slice(-2);if(!terms.some(s=>s.semester===semester))terms.push({semester,label:label+' '+year});}if(value&&!terms.some(s=>s.semester===value))terms.push({semester:value,label:termLabel(value)});return `${autodetect?'<option value="">Detect from the file</option>':''}${terms.map(s=>`<option value="${attr(s.semester)}"${s.semester===value?' selected':''}>${esc(s.label)}</option>`).join('')}`;}
function importWorkspace(){
  const p=state.preview,kind=state.importKind;const names={regis:'Official REGIS roster',canvas:'Canvas assessment scores',proposals:'Instructor grade proposals',instructors:'Instructor assignments'};
  return `<section class="card"><div class="card-header"><div><h2>${esc(names[kind])}</h2><p>${p?'File preview is ready. Review the scope and score mapping before applying.':'Files are read on this computer. No records change until you apply the import.'}</p></div>${p?button('Choose another file','reset-import',false):''}</div><div class="card-body"><h3 class="step-title"><span class="step-number">1</span> Choose the file and semester</h3>${!p?`<label class="upload-box"><strong>Select a CSV or Excel file</strong><span>REGIS and Canvas exports are supported without reformatting.</span><input id="import-file" type="file" accept=".csv,.xlsx,.xls" aria-label="Choose import file"></label>`:`<p class="small-text"><strong>${esc(p.filename||state.importFile?.name||'Selected file')}</strong> · ${integer(p.counts?.rows)} rows · ${p.semester_detected?'Semester detected from the file':p.needs_semester?'Choose a semester below':'Semester selected'}</p>`}<div class="form-grid"><div class="field"><label for="import-semester">Semester</label><select id="import-semester">${semesterOptions(p?.semester||state.importSemester,true)}</select><p class="field-help">The detected semester is shown in the preview. Confirm it before applying.</p></div>${kind==='regis'?`<div class="field"><label for="import-scope">Roster scope</label><select id="import-scope"><option value="semester"${state.importScope==='semester'?' selected':''}>Entire semester</option><option value="sections"${state.importScope==='sections'?' selected':''}>Selected sections only</option></select><p class="field-help">A partial roster should replace only the sections it contains.</p></div><div class="field full" id="scope-sections-field"${state.importScope==='sections'?'':' hidden'}><label for="import-sections">Sections to replace</label><input id="import-sections" value="${attr((state.importSections.length?state.importSections:p?.sections_detected||[]).join(', '))}" placeholder="For example: 01, 02, 03"><p class="field-help">Separate section numbers with commas. Other sections are left unchanged.</p></div>`:''}</div>${kind==='regis'?'<p class="note amber">The new roster is authoritative for the selected scope. Students absent from it are removed from that roster, while their history is preserved. Absence alone never creates a W grade.</p>':kind==='canvas'?'<p class="note">Included columns update their existing scores, including clearing a score when the new cell is blank. Columns absent from the upload stay unchanged. Homework and quiz columns are already processed category averages.</p>':kind==='instructors'?'<p class="note">Use columns named Section, Instructor, and Email. Choose the semester above. Instructor assignments are used for TZ follow-up and grade-review reports.</p>':'<p class="note">Use columns named RUID or NetID and Grade. Section and Semester are optional. Proposed grades do not replace official REGIS grades.</p>'}${!p?`<div class="action-row">${button('Preview import →','preview-import',true)}</div>`:''}</div></section>${p?previewPanel(p):''}`;
}
function renderImports(){
  if(state.proposalImportOpen){renderProposalImport();return;}
  content.innerHTML=heading('Imports','Bring in a roster or score file, check the changes, and apply them with an undo record.')+`<div class="import-kind-grid">${[['regis','REGIS roster','Replace the semester or selected sections with the official roster.'],['canvas','Canvas scores','Update included assessment columns for matched students.']].map(([k,title,desc])=>`<button class="import-kind${state.importKind===k?' active':''}" data-import-kind="${k}"><strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>`+importWorkspace()+historyPanel(state.cache.imports||[]);
}
let proposalDialog;
function renderProposalImport(){
  if(!proposalDialog){
    proposalDialog=document.createElement('dialog');proposalDialog.id='proposal-import-dialog';proposalDialog.setAttribute('aria-labelledby','proposal-import-title');document.body.append(proposalDialog);
    proposalDialog.addEventListener('cancel',event=>{event.preventDefault();closeProposalImport();});
  }
  proposalDialog.innerHTML=`<div class="dialog-header"><div><h2 id="proposal-import-title">Import proposed grades</h2><p>Load instructor proposals, then compare them in Grade Review. Official grades stay separate.</p></div><button class="dialog-close" data-action="close-proposals" aria-label="Close proposed-grade import">×</button></div><div class="proposal-import-body">${importWorkspace()}<div class="action-row">${button('Cancel','close-proposals')}</div></div>`;
  if(!proposalDialog.open)proposalDialog.showModal();
}
function closeProposalImport(){
  if(state.importBusy){notify('Wait for the current import step to finish.');return;}
  proposalDialog?.close();if(proposalDialog)proposalDialog.innerHTML='';state.proposalImportOpen=false;
  if(state.proposalReturnImport){Object.assign(state,state.proposalReturnImport);state.proposalReturnImport=null;}
}
function openProposalImport(){
  state.proposalReturnImport=Object.fromEntries(['importKind','preview','importFile','importSemester','importScope','importSections'].map(key=>[key,state[key]]));
  Object.assign(state,{proposalImportOpen:true,importKind:'proposals',preview:null,importFile:null,importSemester:importDefaultSemester(),importScope:'semester',importSections:[]});
  renderProposalImport();
}
function previewPanel(p){const c=p.counts||{};return `<section class="card"><div class="card-header"><div><h2>Review proposed changes</h2><p>${esc(termLabel(p.semester))} · ${esc(p.scope==='sections'?'Selected sections':'Entire semester')} · No changes have been applied.</p></div><span class="badge ${p.can_commit?'green':'amber'}">${p.can_commit?'Ready to apply':'Needs attention'}</span></div><div class="card-body"><h3 class="step-title"><span class="step-number">2</span> Check the preview</h3><div class="metric-grid">${metric('New records',integer(c.new??c.added??0),'Will be added',true)}${metric('Updated records',integer(c.updated??0),'Existing records with changes')}${metric('Removed from roster',integer(c.removed??0),'History remains available')}${metric('Unmatched / invalid',integer((c.unmatched||0)+(c.invalid||0)),'Shown below when available')}</div>${p.columns?.length&&p.kind==='canvas'?`<p class="small-text muted">Only included columns are imported. Columns belonging to versions of the same exam should use the same assessment group (for example, midterm1 for all versions of Midterm 1). Existing classification and selection rules are shown beside each column.</p><div class="table-scroll"><table class="mapping-table"><thead><tr><th>Use</th><th>Source column</th><th>Assessment group</th><th>Display name</th><th>Out of</th><th>How it is used</th></tr></thead><tbody>${p.columns.map((col,i)=>`<tr data-mapping="${i}"><td><input type="checkbox" data-map="include" aria-label="Include ${attr(col.header)}"${col.include?' checked':''}></td><td class="score-name">${esc(col.header)}<span class="secondary-text">Column ${columnLetter(Number(col.column))}</span></td><td><input data-map="assessment_key" value="${attr(col.assessment_key||'')}" aria-label="Assessment group for ${attr(col.header)}" list="assessment-keys"></td><td><input data-map="assessment_name" value="${attr(col.assessment_name||'')}" aria-label="Assessment name for ${attr(col.header)}"></td><td class="max-score"><input data-map="max_points" type="number" min="0.001" step="any" value="${attr(col.max_points??100)}" aria-label="Maximum points for ${attr(col.header)}"></td><td><span class="badge gray">${esc(({version:'Best version',aggregate:'Category average',ignore:'Not imported',consolidated:'Combined score',adjusted:'Adjusted score',replacement:'Replacement',component:'Exam component'})[col.role]||col.role||'Score')}</span></td></tr>`).join('')}</tbody></table></div><datalist id="assessment-keys">${state.boot.assessments.filter(a=>a.semester===p.semester).map(a=>`<option value="${attr(a.assessment_key)}">${esc(a.label)}</option>`).join('')}</datalist>`:''}${p.issues?.length?`<div class="note amber"><strong>${integer(p.issues.length)} items to check</strong><ul>${p.issues.slice(0,50).map(x=>`<li>${x.row?'Row '+integer(x.row)+': ':''}${esc(x.message)}</li>`).join('')}</ul>${p.issues.length>50?'<p>Additional items are retained in the local import record.</p>':''}</div>`:''}${p.examples?.length?`<h3 class="section-title">Changes in this preview</h3><div class="table-scroll"><table><thead><tr><th>Student</th><th>NetID</th><th>Action</th></tr></thead><tbody>${p.examples.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.netid)}</td><td>${esc(statusLabel(x.action))}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="action-row">${button('Update preview','update-preview')}${button('Apply this import','commit-import',true,p.can_commit?'':'disabled')}</div><p class="field-help">If you change the semester, scope, or column mapping, update the preview before applying.</p></div></section>`;}
function columnLetter(index){let n=index+1,out='';while(n>0){out=String.fromCharCode(65+(n-1)%26)+out;n=Math.floor((n-1)/26);}return out;}
function historyPanel(rows){return `<section class="card"><div class="card-header"><div><h2>Import history</h2><p>Undo restores the records affected by an import.</p></div>${button('Refresh history','refresh-imports')}</div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>File</th><th>Semester</th><th>Imported</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.filename||'Import')}</strong><span class="secondary-text">${esc(({regis:'REGIS roster',canvas:'Canvas scores',proposals:'Proposed grades',instructors:'Instructor assignments'})[r.kind]||r.kind)}</span></td><td>${esc(termLabel(r.semester))}</td><td>${esc(formatDate(r.created_at))}</td><td><span class="badge ${r.status==='undone'?'gray':'green'}">${esc(statusLabel(r.status||'Applied'))}</span></td><td>${r.can_undo?button('Undo import','undo-import',false,`data-import-id="${attr(r.import_id)}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('No imports yet','Your next roster or score import will appear here with its change history.')}</section>`;}
function formatDate(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});}
function importInputs(){const semester=$('#import-semester')?.value||'';const scope=$('#import-scope')?.value||'semester';const sections=($('#import-sections')?.value||'').split(/[,;\n]/).map(v=>v.trim()).filter(Boolean);state.importSemester=semester;state.importScope=scope;state.importSections=sections;return {semester,scope,sections};}
function mappings(){return (state.preview?.columns||[]).map((column,i)=>{const row=$(`[data-mapping="${i}"]`);if(!row)return column;return {...column,include:$('[data-map="include"]',row).checked,assessment_key:$('[data-map="assessment_key"]',row).value.trim(),assessment_name:$('[data-map="assessment_name"]',row).value.trim(),max_points:Number($('[data-map="max_points"]',row).value)};});}
async function previewImport(update=false){
  const input=importInputs();if(input.scope==='sections'&&!input.sections.length)throw new Error('Enter the section numbers included in this roster.');
  let body;if(update){body={preview_id:state.preview.preview_id,...input,mappings:mappings()};}else{const file=$('#import-file')?.files?.[0];if(!file)throw new Error('Choose a file to import first.');state.importFile=file;body={kind:state.importKind,filename:file.name,data:await fileBase64(file),...input};}
  const p=await request('/imports/preview',{method:'POST',body:JSON.stringify(body)});state.preview={...p,filename:p.filename||state.importFile?.name};state.importSemester=p.semester||input.semester;state.importScope=p.scope||input.scope;if(!state.importSections.length)state.importSections=p.sections_detected||[];renderImports();notify(p.can_commit?'Preview ready. Check the changes before applying.':'Preview ready. Resolve the highlighted items before applying.');
}
async function fileBase64(file){if(file.size>100*1024*1024)throw new Error('Please choose a file smaller than 100 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('The selected file could not be read.'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});}
async function refreshBoot(){state.boot=await request('/bootstrap');}
async function commitImport(){if(!state.preview)throw new Error('Preview the import first.');const r=await request('/imports/commit',{method:'POST',body:JSON.stringify({preview_id:state.preview.preview_id})});state.preview=null;state.importFile=null;await refreshBoot();if(state.proposalImportOpen){state.importBusy=false;closeProposalImport();}await loadTab();notify(r.message||'Import applied. You can undo it in import history.');}
function policyShape(policy){
  const weights=policy.weights||policy.components||{};
  return {weights:Array.isArray(weights)?weights.map((w,i)=>({key:w.key||w.assessment_key||w.name||String(i),label:w.label||w.name||w.key||w.assessment_key,weight:w.weight??w.percent??0,original:w,index:i})):Object.entries(weights).map(([key,w])=>({key,label:typeof w==='object'?(w.label||key):key,weight:typeof w==='object'?(w.weight??w.percent??0):w,original:w})),cutoffs:policy.cutoffs||policy.thresholds||policy.grade_cutoffs||{},bump:policy.bump||policy.final_exam_bump||{},raw:policy};
}
function humanAssessment(key){return ({homework:'Homework average',quiz:'Quiz average',quizzes:'Quiz average',wrappers:'Wrappers / surveys',surveys:'Wrappers / surveys',final:'Final exam',final_exam:'Final exam',precalc:'Precalculus exam',midterm1:'Midterm 1',midterm2:'Midterm 2',midterm3:'Midterm 3',midterm4:'Midterm 4',midterms:'Midterms'})[key]||key.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function effectiveWeightTotal(weights,policy=state.policy||{}){const drop=Number(policy.drop_lowest_midterm||0);return weights.reduce((sum,w)=>sum+Number(w.weight||0),0)-weights.filter(w=>/^midterm\d+$/i.test(w.key)).map(w=>Number(w.weight)||0).sort((a,b)=>a-b).slice(0,drop).reduce((sum,w)=>sum+w,0);}
function teachingRows(term){const rows=new Map();for(const a of state.boot.teaching_assignments||[]){if(a.semester!==term)continue;const r=rows.get(a.section)||{section:a.section,lecturer:[],recitation:[]};r[a.role].push(a.name);rows.set(a.section,r);}return [...rows.values()].sort((a,b)=>a.section.localeCompare(b.section)).map(r=>[r.section,r.lecturer.join('; '),r.recitation.join('; ')].join('\t')).join('\n');}
function renderSettings(){
  const p=state.policy||{},v=policyShape(p);state.cache.policyShape=v;
  const floor=p.minimum_bump_average??p.bump_minimum_rounded_average??p.bump_min_average??p.bump_minimum??v.bump.minimum_average??v.bump.min_average??v.bump.minimum??null;
  const enabled=p.bump_enabled??v.bump.enabled??(typeof p.final_exam_bump==='boolean'?p.final_exam_bump:true);
  const rounded=p.round_average??p.round_course_average??p.bump_min_uses_rounded??p.bump_minimum_rounded??v.bump.use_rounded_average??v.bump.rounded??true;
  content.innerHTML=heading('Course settings','Keep each semester’s grading policy and instructor assignments together.')+`<section class="card"><div class="card-header"><div><h2>Semester grading policy</h2><p>Policies are specific to each semester. Historical records retain their original semester rules.</p></div></div><div class="card-body policy-term-grid"><div class="policy-list" aria-label="Policy semester">${state.boot.semesters.map(s=>`<button class="policy-choice${s.semester===state.policyTerm?' active':''}" data-policy-term="${attr(s.semester)}">${esc(s.label)}</button>`).join('')}<button class="policy-choice" data-action="add-policy-term">+ Add next semester</button></div><form id="policy-form"><h3 class="step-title">${esc(termLabel(state.policyTerm))}</h3><p class="small-text muted">Category averages are already processed by instructors. The app applies these weights directly.</p><div id="weight-fields">${v.weights.length?v.weights.map((w,i)=>`<div class="weight-row"><label for="weight-${i}">${esc(humanAssessment(w.label||w.key))}</label><input id="weight-${i}" type="number" step="0.01" min="0" max="100" data-weight="${i}" value="${attr(w.weight)}"><span class="unit">% <button type="button" class="button small" data-action="remove-policy-component" data-index="${i}" aria-label="Remove ${attr(w.key)}">Remove</button></span></div>`).join(''):'<p class="note amber">No weights have been set for this semester yet.</p>'}</div><button type="button" class="button small" data-action="add-policy-component">Add component</button><p id="weight-total" class="small-text muted">Total weight: ${percent(effectiveWeightTotal(v.weights,p))}${p.drop_lowest_midterm?' after dropping '+p.drop_lowest_midterm+' midterm(s)':''}</p><div class="subtle-divider"></div><h3 class="step-title">Letter-grade cutoffs</h3><p class="field-help">Minimum course percentage for each grade, before any final-exam bump.</p><div class="policy-cutoffs">${['A','B+','B','C+','C','D','F'].map(g=>`<div><label for="cutoff-${g.replace('+','plus')}">${g}</label><input id="cutoff-${g.replace('+','plus')}" data-cutoff="${g}" type="number" min="0" max="100" step="0.01" value="${attr(v.cutoffs[g]??'')}" aria-label="Minimum percentage for ${g}"></div>`).join('')}</div><div class="subtle-divider"></div><label class="check-option"><input type="checkbox" id="policy-bump-enabled"${enabled?' checked':''}><span>Allow a one-step bump when the final-exam letter is higher</span></label><div class="form-grid policy-adjustments"><div class="field"><label for="policy-bump-floor">Minimum average needed for the bump</label><input id="policy-bump-floor" type="number" min="0" max="100" step="0.01" value="${attr(floor??'')}" placeholder="No minimum"><p class="field-help">Leave blank for no minimum. Set this semester’s rule explicitly.</p></div><fieldset class="policy-rounding"><legend>Rounding</legend><label class="check-option"><input id="policy-round-average" type="checkbox"${rounded?' checked':''}><span>Round the course average to a whole number</span></label><label class="check-option"><input id="policy-round-final" type="checkbox"${(p.round_final??p.round_final_score??true)?' checked':''}><span>Round the final-exam score to a whole number</span></label><p class="field-help">The minimum needed for a bump is always checked against the rounded course average.</p></fieldset></div><p class="note">XF is always treated as F in calculations. W has no course average. TF and TTZ are normalized to TZ. Instructor-proposed grades remain separate from official grades.</p><div class="action-row">${button('Save grading policy','save-policy',true)}</div></form></div></section><section class="card"><div class="card-header"><div><h2>Lecturer and recitation assignments</h2><p>Linked through semester and section. Used for instructor filters and follow-up reports.</p></div>${button('Import instructor file','open-instructors')}</div><div class="card-body"><div class="form-grid"><div class="field"><label for="instructor-semester">Semester</label><select id="instructor-semester">${semesterOptions(state.policyTerm)}</select></div><div class="field full"><label for="instructor-rows">Section, lecturer, and recitation instructor</label><textarea id="instructor-rows" class="instructor-paste" placeholder="Section&#9;Lecturer&#9;Recitation&#10;001&#9;Lecturer name&#9;Recitation instructor">${esc(teachingRows(state.policyTerm))}</textarea><p class="field-help">Paste three columns from a spreadsheet, separated by tabs: Section, Lecturer, Recitation. Separate co-instructors with semicolons. A header row is optional; blank roles clear that role for the supplied section.</p></div></div><div class="action-row">${button('Save instructor assignments','save-instructors',true)}</div></div></section>`;
}
function capturePolicy(){
  const p=state.policy||{};p.weights=Object.fromEntries((state.cache.policyShape?.weights||[]).map((w,i)=>[w.key,Number($(`[data-weight="${i}"]`)?.value||0)]));
  p.cutoffs=Object.fromEntries($$('[data-cutoff]').filter(n=>n.value!=='').map(n=>[n.dataset.cutoff,Number(n.value)]));
  p.minimum_bump_average=$('#policy-bump-floor')?.value===''?null:Number($('#policy-bump-floor')?.value);p.bump_enabled=!!$('#policy-bump-enabled')?.checked;p.round_average=!!$('#policy-round-average')?.checked;p.round_final=!!$('#policy-round-final')?.checked;state.policy=p;
}
async function savePolicy(){
  const p=structuredClone(state.policy||{}),v=state.cache.policyShape;
  const weights=v.weights.map((w,i)=>({...w,weight:Number($(`[data-weight="${i}"]`).value)}));if(weights.some(w=>!Number.isFinite(w.weight)||w.weight<0))throw new Error('Enter a valid nonnegative weight for every component.');
  const drop=Number(p.drop_lowest_midterm||0),midtermWeights=weights.filter(w=>/^midterm\d+$/i.test(w.key)).map(w=>w.weight).sort((a,b)=>a-b);const effectiveTotal=weights.reduce((n,w)=>n+w.weight,0)-midtermWeights.slice(0,drop).reduce((n,w)=>n+w,0);
  if(weights.length&&Math.abs(effectiveTotal-100)>.011)throw new Error('Course weights must add to 100% after any saved midterm-drop rule.');
  const key=p.weights!==undefined?'weights':p.components!==undefined?'components':'weights';
  if(Array.isArray(p[key]))p[key]=weights.map(w=>({...w.original,[w.original.weight!==undefined?'weight':w.original.percent!==undefined?'percent':'weight']:w.weight}));else p[key]=Object.fromEntries(weights.map(w=>[w.key,typeof w.original==='object'?{...w.original,[w.original.weight!==undefined?'weight':w.original.percent!==undefined?'percent':'weight']:w.weight}:w.weight]));
  const cutoffs={};$$('[data-cutoff]').forEach(node=>{if(node.value!=='')cutoffs[node.dataset.cutoff]=Number(node.value);});p.cutoffs=cutoffs;
  const floor=$('#policy-bump-floor').value===''?null:Number($('#policy-bump-floor').value),enabled=$('#policy-bump-enabled').checked,rounded=$('#policy-round-average').checked;
  p.bump_enabled=enabled;p.minimum_bump_average=floor;p.round_average=rounded;p.round_final=$('#policy-round-final').checked;
  const r=await request('/policy',{method:'POST',body:JSON.stringify({semester:state.policyTerm,policy:p})});state.policy=p;state.policyDirty=false;await refreshBoot();notify(r.message||'Grading policy saved.');
}
function parseInstructorRows(text){return text.split(/\r?\n/).filter(r=>r.trim()).map(row=>{const cells=row.includes('\t')?row.split('\t'):row.split(',');return {section:cells[0]?.trim(),lecturer:cells[1]?.trim()||'',recitation:cells[2]?.trim()||''};}).filter(r=>!/^section$/i.test(r.section));}
async function saveInstructors(){const rows=parseInstructorRows($('#instructor-rows').value);if(rows.some(r=>!r.section||(!r.lecturer&&!r.recitation)))throw new Error('Every row needs a section and at least one instructor.');const r=await request('/instructors',{method:'POST',body:JSON.stringify({semester:$('#instructor-semester').value,rows})});state.instructorDirty=false;await refreshBoot();notify(r.message||'Teaching assignments saved.');}
function markPreviewDirty(){if(!state.preview)return;const btn=$('[data-action="commit-import"]');if(btn)btn.disabled=true;const note=$('.card:has([data-action="commit-import"]) .card-header .badge');if(note){note.className='badge amber';note.textContent='Update preview first';}}
async function act(action,target){
  if(action==='reload')return loadTab();
  if(action==='clear-filters'){recordFilters.clear();state.filtersTouched=true;state.page=1;return loadTab();}
  if(action==='search'){state.q=$('#student-search').value.trim();state.page=1;return loadTab();}
  if(action==='previous-page'){state.page=Math.max(1,state.page-1);return loadTab();}
  if(action==='next-page'){state.page++;return loadTab();}
  if(action==='close-dialog'){dialog.close();return;}
  if(action==='print'){window.print();return;}
  if(action==='open-proposals')return openProposalImport();
  if(action==='close-proposals')return closeProposalImport();
  if(action==='open-instructors'){state.tab='imports';window.location.hash='imports';state.importKind='instructors';state.preview=null;state.importSemester=state.policyTerm||currentTerm();return loadTab();}
  if(action==='reset-import'){state.preview=null;state.importFile=null;return renderImports();}
  if(action==='preview-import')return previewImport(false);
  if(action==='update-preview')return previewImport(true);
  if(action==='commit-import')return commitImport();
  if(action==='refresh-imports')return loadTab();
  if(action==='undo-import'){const id=target.dataset.importId;if(!await window.GWorksDialogs.confirm('Undo this import? The records it changed will return to their previous saved state.'))return;const r=await request('/imports/undo',{method:'POST',body:JSON.stringify({import_id:id})});await refreshBoot();await loadTab();notify(r.message||'Import undone.');return;}
  if(action==='save-policy')return savePolicy();
  if(action==='save-instructors')return saveInstructors();
  if(action==='add-policy-component'||action==='remove-policy-component'){
    capturePolicy();
    if(action==='add-policy-component'){const key=await window.GWorksDialogs.prompt('Component name (for example homework, midterm1, or final):','');if(!key)return;if(!/^[a-z][a-z0-9_]{0,63}$/.test(key))throw Error('Use a lowercase name with letters, numbers, or underscores.');if(Object.hasOwn(state.policy.weights,key))throw Error('This component is already listed.');state.policy.weights[key]=0;}
    else {const key=state.cache.policyShape.weights[Number(target.dataset.index)]?.key;if(key)delete state.policy.weights[key];}
    state.policyDirty=true;renderSettings();return;
  }
  if(action==='add-policy-term'){const term=await window.GWorksDialogs.prompt('Semester code (for example, Sp27):',calendarTerm());if(!term)return;if(!/^(Sp|Fa|Su)\d{2}$/.test(term))throw new Error('Use a semester code such as Sp27, Su27, or Fa27.');state.policyTerm=term;return loadTab();}
}
document.addEventListener('click',async event=>{
  const nav=event.target.closest('[data-tab]');if(nav){if(state.proposalImportOpen){if(state.importBusy)return;closeProposalImport();}if(nav.dataset.tab!==state.tab)recordFilters.cancel();state.tab=nav.dataset.tab;if(!state.filtersTouched)defaultSemesters();window.location.hash=state.tab;return loadTab();}
  const dropdown=event.target.closest('[data-filter-toggle]');if(dropdown){const key=dropdown.dataset.filterToggle,node=$(`[data-filter-options="${key}"]`),open=node.hidden;$$('.multi-popover').forEach(p=>p.hidden=true);$$('[data-filter-toggle]').forEach(p=>p.setAttribute('aria-expanded','false'));node.hidden=!open;dropdown.setAttribute('aria-expanded',String(open));return;}
  if(!event.target.closest('.multi-filter')){$$('.multi-popover').forEach(p=>p.hidden=true);$$('[data-filter-toggle]').forEach(p=>p.setAttribute('aria-expanded','false'));}
  const student=event.target.closest('[data-student]');if(student)return showStudent(student.dataset.student);
  const score=event.target.closest('[data-score-toggle]');if(score){const row=$(`[data-score-row="${score.dataset.scoreToggle}"]`);row.hidden=!row.hidden;score.setAttribute('aria-expanded',String(!row.hidden));score.textContent=row.hidden?'Scores':'Hide scores';return;}
  const report=event.target.closest('[data-report]');if(report){state.report=report.dataset.report;return renderReports(state.cache.reports);}
  const kind=event.target.closest('[data-import-kind]');if(kind){state.importKind=kind.dataset.importKind;state.preview=null;state.importFile=null;return renderImports();}
  const policy=event.target.closest('[data-policy-term]');if(policy){state.policyTerm=policy.dataset.policyTerm;return loadTab();}
  const action=event.target.closest('[data-action]');if(!action||action.disabled)return;event.preventDefault();const oldText=action.textContent;const busy=['preview-import','update-preview','commit-import','undo-import','save-policy','save-instructors'].includes(action.dataset.action);if(busy){state.importBusy=true;action.disabled=true;action.textContent='Working…';}try{await act(action.dataset.action,action);}catch(error){notify(error.message,true);}finally{if(busy)state.importBusy=false;if(busy&&action.isConnected){action.disabled=false;action.textContent=oldText;if(state.preview&&!state.preview.can_commit&&action.dataset.action==='commit-import')action.disabled=true;}}
});
document.addEventListener('change',event=>{
  const t=event.target;
  if(t.closest('#policy-form'))state.policyDirty=true;
  if(t.dataset.filter){const key=t.dataset.filter;state.filters[key]=$$(`[data-filter="${key}"]:checked`).map(x=>x.value);const options=availableFilterOptions(key),labels=options.filter(o=>state.filters[key].includes(String(o.value))).map(o=>o.label);$(`[data-filter-toggle="${key}"] .selected-text`).textContent=labels.join(', ')||'All selected';return;}
  if(t.id==='assessment-select'){state.assessment=t.value;return loadTab();}
  if(t.id==='exclude-zero'){state.excludeZero=t.checked;return loadTab();}
  if(t.id==='include-w'){state.includeW=t.checked;return loadTab();}
  if(t.id==='include-tz'){state.includeTZ=t.checked;return loadTab();}
  if(t.id==='review-only'){state.reviewOnly=t.checked;return loadTab();}
  if(t.id==='tz-only'){state.tzOnly=t.checked;return loadTab();}
  if(t.id==='import-scope'){state.importScope=t.value;$('#scope-sections-field').hidden=t.value!=='sections';markPreviewDirty();return;}
  if(t.id==='import-semester'||t.id==='import-sections'||t.dataset.map)markPreviewDirty();
  if(t.id==='instructor-semester')$('#instructor-rows').value=teachingRows(t.value);
});
document.addEventListener('input',event=>{const t=event.target;if(t.closest('#policy-form'))state.policyDirty=true;if(t.id==='instructor-rows')state.instructorDirty=true;if(t.dataset.weight){const weights=state.cache.policyShape.weights.map((w,i)=>({...w,weight:Number($(`[data-weight="${i}"]`).value||0)}));const sum=effectiveWeightTotal(weights);$('#weight-total').textContent='Total weight: '+percent(sum)+(state.policy.drop_lowest_midterm?' after the saved midterm-drop rule':'');$('#weight-total').style.color=Math.abs(sum-100)>.011?'var(--red)':'';}if(t.dataset.map||t.id==='import-sections')markPreviewDirty();});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='student-search-form')act('search');});
window.addEventListener('hashchange',()=>{const tab=window.location.hash.slice(1);if(state.boot&&['students','reports','imports','review','settings'].includes(tab)&&tab!==state.tab){if(state.proposalImportOpen){if(state.importBusy)return;closeProposalImport();}recordFilters.cancel();state.tab=tab;if(!state.filtersTouched)defaultSemesters();loadTab();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$$('.multi-popover').forEach(p=>p.hidden=true);$$('[data-filter-toggle]').forEach(p=>p.setAttribute('aria-expanded','false'));}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
window.addEventListener('beforeunload',event=>{if(state.policyDirty||state.instructorDirty||state.preview||state.importBusy){event.preventDefault();event.returnValue='';}});
(async()=>{try{state.boot=await request('/bootstrap');const mark=document.querySelector('.brand-mark');if(mark)mark.textContent=state.boot.course?.code||'G';const label=document.querySelector('[data-course-name]');if(label)label.textContent=courseName();state.policyTerm=currentTerm();const tab=window.location.hash.slice(1);if(['students','reports','imports','review','settings'].includes(tab))state.tab=tab;defaultSemesters();await loadTab();}catch(error){content.innerHTML=heading('The local app could not open','Please close this page, reopen G-Vault, and try again.')+`<p class="note error">${esc(error.message)}</p>`;}})();
